"use client";

import type { DataProvider } from "react-admin";
import { authStore } from "./authStore";

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3333";

const http = async (
  path: string,
  options: RequestInit = {},
): Promise<unknown> => {
  const token = authStore.getToken();

  const response = await fetch(`${API_URL}${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options.headers ?? {}),
    },
  });

  if (!response.ok) {
    const error = new Error("API error") as Error & { status?: number };
    error.status = response.status;
    throw error;
  }

  if (response.status === 204) return null;
  return response.json();
};

const rawDataProvider = {
  getList: async (resource: string, params: any) => {
    if (resource === "products") {
      const page = params.pagination?.page ?? 1;
      const perPage = params.pagination?.perPage ?? 10;

      const data = (await http(
        `/products?page=${page}&limit=${perPage}`,
      )) as {
        products: Record<string, unknown>[];
        pagination: { total: number };
      };

      return {
        data: data.products,
        total: data.pagination.total,
      };
    }

    if (resource === "categories") {
      const data = (await http("/categories/all")) as Record<string, unknown>[];
      return {
        data,
        total: data.length,
      };
    }

    throw new Error(`Unsupported resource: ${resource}`);
  },

  getOne: async (resource: string, params: any) => {
    if (resource === "products") {
      const data = (await http(`/products/${params.id}`)) as Record<
        string,
        unknown
      >;
      return { data };
    }

    if (resource === "categories") {
      const data = (await http(`/categories/${params.id}`)) as {
        category?: Record<string, unknown>;
        id?: number | string;
      };
      return { data: data.category ?? data };
    }

    throw new Error(`Unsupported resource: ${resource}`);
  },

  getMany: async () => ({ data: [] }),
  getManyReference: async () => ({ data: [], total: 0 }),
  update: async () => {
    throw new Error("Update not implemented");
  },
  updateMany: async () => ({ data: [] }),
  create: async () => {
    throw new Error("Create not implemented");
  },
  delete: async () => {
    throw new Error("Delete not implemented");
  },
  deleteMany: async () => ({ data: [] }),
};

export const dataProvider = rawDataProvider as unknown as DataProvider;
